The batch_invert_and_mul function batch-inverts an array of elements (values) and
multiplies it by a given coefficient. However, if the array contains zeros, the function will
ignore them, leaving them unchanged. This behavior could cause unexpected issues, as the
array would be successfully inverted even though some of its elements are not actually
invertible.

 /// Batch invert [`PrimeField`] elements and multiply all with given coefficient.
 pub fn batch_invert_and_mul<F: PrimeField>(values: &mut [F], coeff: &F) {
 let products = values
 .iter()
 .filter(|value| !value.is_zero_vartime())
 .scan(F::one(), |acc, value| {
 *acc *= value;
 Some(*acc)
 })
 .collect_vec();

 let mut all_product_inv = products.last().unwrap().invert().unwrap() * coeff;

 for (value, product) in values
 .iter_mut()
 .rev()
 .filter(|value| !value.is_zero_vartime())
 .zip(products.into_iter().rev().skip(1).chain(Some(F::one())))
 {
 let mut inv = all_product_inv * product;
 mem::swap(value, &mut inv);
 all_product_inv *= inv;
 }
 }

