 // base on the proof data
 // Also notice the sibling can be nil if the trie has only one leaf
 func (t *ZkTrie) ProveWithDeletion(key []byte, fromLevel uint, writeNode func(*Node)
 error, onHit func(*Node, *Node)) error {
 [...]
 }

