E. Proof of Concept for TOB-ALEO-12

This appendix contains a proof of concept that shows the behavior of the
refresh_and_insert function, which causes the issue described in finding TOB-ALEO-12.

Figure E.1 shows the main.rs file, and figure E.2 shows the required Cargo.toml file.
Figure E.3 shows the output of the program, where we can see that the
refresh_and_insert call to overwrite the item with a key value of 0 does not return the
previously existing entry; instead, it returns a None.

use linked_hash_map::LinkedHashMap;
use parking_lot::RwLock;
use std::hash::Hash;

const MAX_CACHE_SIZE: usize = 4;

fn refresh<K: Eq + Hash, V>(map: &RwLock<LinkedHashMap<K, V>>) {
 let mut map_write = map.write();
 while map_write.len() >= MAX_CACHE_SIZE {
 map_write.pop_front();
 }
}

fn refresh_and_insert<K: Eq + Hash, V>(map: &RwLock<LinkedHashMap<K, V>>,
 key: K, value: V) -> Option<V> {
 refresh(map);
 map.write().insert(key, value)
}

fn main() {
 let map : RwLock<LinkedHashMap<i64, i64>> =
RwLock::new(LinkedHashMap::with_capacity(MAX_CACHE_SIZE));

 { // use scope so the underlying lock is released afterwards
 let mut w = map.write();
 for i in 0..MAX_CACHE_SIZE {
 let i = i.try_into().unwrap();
 w.insert(i, 10+i);
 }
 }

 println!("Printing map items:");
 for i in 0..6 {
 let r = map.read();
 let v = r.get(&i);
 println!("k={} v={:?}", i, v);
 }

 let val = refresh_and_insert(&map, 0, 123);
 println!("refreshed k=0 v={:?}", val);

