Return the maximum integer value in the case of a positive, and the minimum integer value
in the case of a negative integer overflow, for the SaturatingAdd and SaturatingMul
functions.

// SaturatingAdd adds two integers without overflow
func SaturatingAdd[T Signed](a, b T) T {
 sum := a + b
 if b > 0 && sum < a {
 return MaxSignedValue[T]()
 }
 if b < 0 && sum > a {
 return MinSignedValue[T]()
 }
 return sum
}

