// SaturatingMul multiply two integers without over/underflow
func SaturatingMul[T Signed](a, b T) T {
 product := a * b
 if b != 0 && product/b != a {
 if (a > 0 && b > 0) || (a < 0 && b < 0) {
 product = MaxSignedValue[T]()
 } else {
 product = MinSignedValue[T]()
 }
 }
 return product
}

