 } else if (opcode == Instructions.F32_CONST) {
 ty = ValueType.F32;
 } else if (opcode == Instructions.F64_CONST) {
 ty = ValueType.F64;
 } else {
 revert("CONST_PUSH_INVALID_OPCODE");
 }

 mach.valueStack.push(Value({valueType: ty, contents:
