 export function getHttpsUrl(url: string): string | null {
 let parsedUrl: URL;

 try {
 parsedUrl = new URL(url);
 } catch {
 try {
 parsedUrl = new URL('http://' + url);
 } catch {
 return null;
 }
 }

 if (!isValidHostname(parsedUrl.hostname)) {
 return null;
 }

 const { host, pathname, search, hash } = parsedUrl;
 return `https://${host}${pathname}${search}${hash}`;
 }

 function isValidHostname(hostname: string): boolean {
 const hostnameRegex =
 /^(?=.{1,253}$)(?:(?:[a-zA-Z0-9](?:[a-zA-Z0-9-]{0,61}[a-zA-Z0-9])?\.)+[a-zA-Z]{2,})$
 /;
 return hostnameRegex.test(hostname);
 }

 Figure 6.2: URL parsing and validation logic
 (src/screens/Browser/utils/getHttpsUrl.ts)

This is presumably to handle the case in which a user mistakenly enters a URL using HTTP
rather than HTTPS. If http were not included in the originWhitelist, then the WebView
would switch away from the Kraken Wallet app to the system’s default browser to render
such pages.

However, most websites will auto-redirect (with HTTP 301, 302, 308, etc.) from HTTP to
HTTPS or not offer HTTP at all. In the event of an HTTP redirect to a whitelisted URL, the
WebView will correctly display the page without switching browsers.

Exploit Scenario
There is a latent bug or a future bug is introduced in the custom URL parsing and
modification code in getHttpsUrl that allows an insecure page to be loaded.

Recommendations:
Short term, document the fact that HTTP URLs are automatically translated to HTTPS
without first checking for redirects.

 Trail of Bits 25 Kraken Wallet In-App Browser
 PUBLIC Security Assessment
Long term, consider removing the whitelist for HTTP URL schemes and/or having the
browser emit a popup warning if a user enters or navigates to an HTTP URL (regardless of
whether the URL is transformed to HTTPS).

