Finding: BalancerPoolToken permit signatures cannot be revoked
Severity: Informational
Difficulty: Medium
Type: Access Controls

Description:
The BalancerPoolToken contract does not implement a way for permit signatures to be
revoked, causing these signatures to remain valid until the deadline.

The BalancerPoolToken contract implements the permit function, allowing users to sign
a payload to allow another user or contract to spend their tokens.

 function permit(
 address owner,
 address spender,
 uint256 amount,
 uint256 deadline,
 uint8 v,
 bytes32 r,
 bytes32 s
 ) public virtual {
 // solhint-disable-next-line not-rely-on-time
 if (block.timestamp > deadline) {
 revert ERC2612ExpiredSignature(deadline);
 }

 bytes32 structHash = keccak256(abi.encode(PERMIT_TYPEHASH, owner, spender,
 amount, _useNonce(owner), deadline));

 bytes32 hash = _hashTypedDataV4(structHash);

 address signer = ECDSA.recover(hash, v, r, s);
 if (signer != owner) {
 revert ERC2612InvalidSigner(signer, owner);
 }

 _vault.approve(owner, spender, amount);
 }

