manager/admin. The function addValidator is restricted to be callable only by addresses
with the VALIDATOR_ROLE, and this function is used to add validators to the system.

 function addValidator(address[] calldata _validators) external onlyRole(VALIDATOR_ROLE)
 {
 for (uint256 i = 0; i < _validators.length; i++) {
 address _validator = _validators[i];
 require(_validator != address(0), "Invalid validator address");
 require(!validators[_validator], "Validator already exists");

 validators[_validator] = true;
 validatorCount += 1;
 }
 }

