 where
 D: Deserializer<'de>,
 {
 let coefficients =
 Vec::<CoefficientCommitment<C>>::deserialize(deserializer)?;
 if coefficients.is_empty() {
 Err(serde::de::Error::custom("Polynomial must not be empty"))
