 // .storeMaybeRef()
 // .storeCoins(0)
 // .storeMaybeRef()
 // .storeAddress(createAddressNone())
 .storeZeroes(4+1+4+1+2)
 .endCell();
 }

 Figure 12.1: A snippet of the transferNotificationPayloadProcess function
 (contracts/router_tolk/operations/router_receive.tolk#L53–L66)

However, if the multihopCell is not null, the cell is never checked to have the correct
format. Therefore, a malformed cell can be attached to the message data and passed along
to the pool contract’s POOL_OPERATION_SWAP operation, which will attempt to parse it:

 cell action_cell = in_msg_body~load_ref();
 slice action_slice = action_cell.begin_parse();
 slice target_address = action_slice~load_msg_addr();
 int ok_forward_amount = action_slice~load_coins();
 cell ok_forward_payload = action_slice~load_maybe_ref();
 int ret_forward_amount = action_slice~load_coins();
 cell ret_forward_payload = action_slice~load_maybe_ref();

