 Some(NotificationIn::NewUnits(units)) => {
 for u in units {
 if self.add_to_store(u).is_err() ||
 self.handle_events().is_err() {
 break
 };
 }
 },
 // (...)
 }
 }
 // (...)
 }
 }
 }

